import math

n = int(input('Enter a positive integer: '))
if n <= 1:
    print(n, 'is neither Prime nor Composite.')
else:
    is_prime = True
    for i in range(2, int(math.isqrt(n)) + 1):
        if n % i == 0:
            is_prime = False
            break
    if is_prime:
        print(n, 'is a PRIME number.')
    else:
        print(n, 'is a COMPOSITE number.')
```

