s = input('Enter a string: ')
vowels = consonants = digits = specials = 0

for ch in s:
    if ch.isalpha():
        if ch.lower() in 'aeiou':
            vowels += 1
        else:
            consonants += 1
    elif ch.isdigit():
        digits += 1
    elif not ch.isspace():
        specials += 1

print(f'Vowels: {vowels}, Consonants: {consonants}, Digits: {digits}, Special Chars: {specials}')
