students = {}

while True:
    print('\n--- CODER & ACCOTAX STUDENT MARKS PORTAL ---')
    print('1. Add / Update Student')
    print('2. Search Marks by Roll Number')
    print('3. Display Class Average & Topper')
    print('4. Exit')
    choice = input('Enter your choice (1-4): ')

    if choice == '1':
        roll = int(input('Enter Roll Number: '))
        name = input('Enter Student Name: ')
        marks = float(input('Enter CS Marks (out of 100): '))
        students[roll] = {'name': name, 'marks': marks}
        print(f'Student {name} registered successfully!')
    elif choice == '2':
        roll = int(input('Enter Roll Number to search: '))
        if roll in students:
            info = students[roll]
            print(f"Found! Name: {info['name']}, Marks: {info['marks']}")
        else:
            print('Error: Roll number not found.')
    elif choice == '3':
        if not students:
            print('No student records available.')
        else:
            total_marks = sum(s['marks'] for s in students.values())
            avg = total_marks / len(students)
            topper = max(students.values(), key=lambda s: s['marks'])
            print(f'Total Students: {len(students)}')
            print(f'Class Average: {avg:.2f}')
            print(f"Highest Scorer: {topper['name']} with {topper['marks']} marks")
    elif choice == '4':
        print('Exiting portal. Thank you!')
        break
    else:
        print('Invalid choice. Please choose 1, 2, 3, or 4.')
```

